def transcribe(file_bytes: bytes, filename="voice.ogg") -> str:
    """Возвращает текст или пустую строку. Оригинал голосового
    никогда не удаляется — расшифровка идёт дополнением к нему."""
    key = openai_key()
    if not key:
        return ""
    try:
        result = _post_multipart(
            "https://api.openai.com/v1/audio/transcriptions",
            {"Authorization": f"Bearer {key}"},
            {"model": TRANSCRIBE_MODEL, "language": "ru",
             "prompt": TRANSCRIBE_HINT},
            "file", filename, file_bytes,
        )
        return (result.get("text") or "").strip()
    except urllib.error.HTTPError as e:
        logging.error(f"Расшифровка не удалась: {e.code} {e.read()[:200]}")
    except Exception as e:
        logging.error(f"Расшифровка не удалась: {e}")
    return ""

def car_fields(ai_filter):
    allowed = getattr(ai_filter, "ALLOWED", {})
    return frozenset(str(name) for name in allowed)

def allowed_for_type(parsed_type, ai_filter, db_module=None):
    if parsed_type == "car":
        return car_fields(ai_filter)
    if parsed_type == "client" and db_module is not None:
        return frozenset(getattr(db_module, "CLIENT_FIELDS", ()))
    return frozenset()

def sanitize_parsed(parsed, ai_filter, db_module=None):
    """Return only fields that have a real destination in the CRM form."""
    if not isinstance(parsed, dict):
        return None
    parsed_type = parsed.get("type")
    allowed = allowed_for_type(parsed_type, ai_filter, db_module)
    if not allowed:
        return None
    raw_fields = parsed.get("fields")
    if not isinstance(raw_fields, dict):
        raw_fields = {}
    fields = {name: value for name, value in raw_fields.items() if name in allowed}
    meta = parsed.get("_meta") if isinstance(parsed.get("_meta"), dict) else {}
    safe_meta = {
        key: meta[key]
        for key in ("model", "elapsed", "source")
        if key in meta and isinstance(meta[key], (str, int, float))
    }
    result = {
        "type": parsed_type,
        "fields": fields,
        "question": None,
        "summary": "Автомобиль" if parsed_type == "car" else "Клиент",
    }
    if safe_meta:
        result["_meta"] = safe_meta
    return result

def parsed_from_data(data, parsed_type="car"):
    return {
        "type": parsed_type,
        "fields": {name: {"value": value} for name, value in data.items()},
        "question": None,
        "summary": "Автомобиль" if parsed_type == "car" else "Клиент",
    }

def clean_car(parsed, ai_filter, extra_text=""):
    safe = sanitize_parsed(parsed, ai_filter)
    if safe is None:
        safe = parsed_from_data({})
    data = ai_filter.clean(safe, extra_text or "")
    allowed = car_fields(ai_filter)
    return {key: value for key, value in data.items() if key in allowed}

def install_prompt(ai_module, ai_filter):
    """Constrain the existing model prompt without changing client parsing."""
    allowed = sorted(car_fields(ai_filter))
    rule = (
        "\n\n[" + PROMPT_MARKER + "] Для type=car разрешены ТОЛЬКО поля: "
        + ", ".join(allowed)
        + ". Не извлекай прочие сведения, не помещай их в summary/question. "
          "Верни только JSON; fields не должен содержать другие ключи."
    )
    for name in ("SYSTEM_PROMPT", "IMAGE_PROMPT"):
        current = str(getattr(ai_module, name, ""))
        if PROMPT_MARKER not in current:
            setattr(ai_module, name, current + rule)
    try:
        ai_module.MAX_TOKENS = min(int(ai_module.MAX_TOKENS), 700)
    except Exception:
        pass

def clean(parsed, extra_text=""):
    """Из разбора оставляем только поля карточки.
    extra_text — исходное сообщение: если разбор что-то потерял, ищем там."""
    flat = flatten(parsed if isinstance(parsed, dict) else {})
    text_all = _all_text(flat)
    if extra_text:
        text_all = text_all + " | " + str(extra_text)
    out = {}
    for field, keys in ALLOWED.items():
        raw = _pick(flat, keys)
        if raw in (None, "", "-", "—"):
            for f2, rx in FALLBACK:
                if f2 != field:
                    continue
                m = rx.search(text_all)
                if m:
                    raw = m.group(1) if m.groups() else m.group(0)
                    break
        if raw in (None, ""):
            continue
        if field == "engine_cc":
            val = _cc(raw)
            if val and not (500 <= val <= 8000):
                val = None
        elif field == "mileage_km":
            val = _km(raw)
            if val and not (0 < val <= 2000000):
                val = None
        elif field == "year":
            val = _year(raw)
            if val and not (1980 <= val <= date.today().year + 1):
                val = None
        elif field == "fuel":
            val = _map(raw, FUEL)
        elif field == "gearbox":
            val = _map(raw, GEARBOX)
        elif field == "drive":
            val = _map(raw, DRIVE)
        elif field == "color":
            val = _map(raw, COLOR)
        elif field == "vin":
            vin = str(raw).upper().replace(" ", "").replace("-", "")
            if len(vin) != 17:
                m = _re.search(r"[A-HJ-NPR-Z0-9]{17}", text_all.upper())
                vin = m.group(0) if m else None
            val = vin
        else:
            val = str(raw).strip()
        if val not in (None, ""):
            out[field] = val
    _log_parsed(parsed, out)
    return out

def render(data, existing=None):
    L = ["<b>Автомобиль</b>"]
    if existing:
        L.append("VIN уже есть в базе: <b>%s</b>" % (existing.get("auto_number") or
                                                     "#%s" % existing["id"]))
        L.append("Дополню эту карточку, новую заводить не буду.")
    L.append("")
    for field in ORDER:
        val = data.get(field)
        if val in (None, ""):
            continue
        if field == "engine_cc":
            val = S.num(val, " см³")
        elif field == "mileage_km":
            val = S.num(val, " км")
        L.append("<b>%s:</b> %s" % (LABELS[field], val))

    return "\n".join(L)

def render_from(parsed, issues=None):
    """Прямая точка входа для team_bot: только поля карточки, ничего лишнего."""
    if not isinstance(parsed, dict) or parsed.get("type") == "client":
        if _ORIG_DRAFT:
            try:
                return _ORIG_DRAFT(parsed, issues)
            except Exception:
                pass
        return ""
    data = clean(parsed)
    return render(data, find_by_vin(data.get("vin")))

def install():
    global _ORIG_DRAFT, _ORIG_REVIEW, _ORIG_DATA
    """Перехватывает вывод разбора: лишнее не доходит ни до чата, ни до базы."""
    try:
        import ai
    except Exception as e:
        log.warning("ai.py не найден, фильтр не поставлен: %s", e)
        return

    def render_draft(parsed, issues=None, *a, **k):
        if isinstance(parsed, dict) and parsed.get("type") == "client":
            return _orig_draft(parsed, issues) if _orig_draft else ""
        data = clean(parsed if isinstance(parsed, dict) else {})
        existing = find_by_vin(data.get("vin"))
        return render(data, existing)

    def render_review(*a, **k):
        return ""      # блок «Проверка» и предположения в чат не выводим

    def to_card_data(parsed, *a, **k):
        if isinstance(parsed, dict) and parsed.get("type") == "client":
            return _orig_data(parsed) if _orig_data else {}
        data = clean(parsed if isinstance(parsed, dict) else {})
        # в старые колонки кладём то, что понимает db.create_card
        out = {}
        for k2, v in data.items():
            if k2 == "engine_cc":
                out["engine"] = v
            elif k2 == "mileage_km":
                out["mileage"] = v
            elif k2 == "condition_text":
                out["condition"] = v
            else:
                out[k2] = v
        out["_clean"] = data          # новые поля дозапишем после создания
        return out

    _orig_draft = getattr(ai, "render_draft", None)
    _orig_data = getattr(ai, "to_card_data", None)
    _ORIG_DRAFT = _orig_draft
    _ORIG_REVIEW = getattr(ai, "render_review", None)
    _ORIG_DATA = _orig_data
    ai.render_draft = render_draft
    ai.render_review = render_review
    ai.to_card_data = to_card_data
    log.info("ai_filter поставлен: в карточку идут только нужные поля")

def store(data, actor, inbox_id=None, card_id=None):
    """Кладёт данные в карточку.
    Новая карточка заводится ТОЛЬКО когда есть VIN.
    Заполненные поля никогда не затираются — дописываются лишь пустые.
    Возвращает (card_id, номер, признак новой) или (None, None, None),
    если заводить нечего.
    """
    existing = None
    if card_id:
        existing = db.get_card("cars", int(card_id))
    if not existing and data.get("vin"):
        existing = find_by_vin(data["vin"])

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if existing.get(field) in (None, "", 0):
                db.update_card_field("cars", card_id, field, value, actor)
        number = existing.get("auto_number")
        if not number:
            with db.connect() as c:
                number = S.next_auto_number(c)
            db.update_card_field("cars", card_id, "auto_number", number, actor)
        novaya = False
    else:
        if not data.get("vin"):
            return None, None, None          # без VIN новую не заводим
        legacy = {k: v for k, v in {
            "brand": data.get("brand"), "model": data.get("model"),
            "year": data.get("year"), "vin": data.get("vin"),
            "fuel": data.get("fuel"), "color": data.get("color"),
        }.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        novaya = True

    if inbox_id:
        # Присланное сообщение к карточке не прикрепляем: скриншоты и документы
        # в галерею попадать не должны. Фото добавляются только кнопкой.
        try:
            db.link_inbox_card(inbox_id, "cars", card_id, actor)
            db.set_inbox_status(inbox_id, db.ST_APPROVED_OWNER, actor)
        except Exception:
            pass

    return card_id, number, novaya

async def save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    staff = db.get_staff(q.from_user.id)
    draft = context.user_data.get("ai_draft")
    if not draft or not staff:
        return                      # пусть отработает обычный обработчик

    parsed = draft.get("parsed") or {}
    if parsed.get("type") == "client":
        return                      # клиентов не трогаем

    data = clean(parsed)
    if not data:
        await q.message.reply_text("Из сообщения нечего взять в карточку.")
        raise ApplicationHandlerStop

    existing = find_by_vin(data.get("vin"))
    actor = staff["user_id"]

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if not existing.get(field):
                db.update_card_field("cars", card_id, field, value, actor)
        note = "Дополнил карточку %s." % (existing.get("auto_number") or "#%d" % card_id)
    else:
        legacy = {"brand": data.get("brand"), "model": data.get("model"),
                  "year": data.get("year"), "vin": data.get("vin"),
                  "fuel": data.get("fuel"), "color": data.get("color")}
        legacy = {k: v for k, v in legacy.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        note = "Открыл новую карточку %s." % number

    # переносим фото и видео из входящего сообщения
    try:
        import team_bot
        foto, video = team_bot.collect_media(draft["inbox_id"])
        if foto:
            import json
            card = db.get_card("cars", card_id)
            have = []
            try:
                have = json.loads(card.get("photos") or "[]")
            except Exception:
                have = []
            norm = [p if isinstance(p, dict) else {"file_id": p, "tag": ""} for p in have]
            for f in foto:
                if not any(p.get("file_id") == f for p in norm):
                    norm.append({"file_id": f, "tag": ""})
            db.update_card_field("cars", card_id, "photos",
                                 json.dumps(norm, ensure_ascii=False), actor)
            try:
                import photo_hide
                photo_hide.archive(card_id, foto, actor)
            except Exception as e:
                log.warning("Архив служебных фото: %s", e)
        if video:
            db.update_card_field("cars", card_id, "video_h", video[0], actor)
    except Exception as e:
        log.warning("Медиа не перенеслись: %s", e)

    try:
        db.link_inbox_card(draft["inbox_id"], "cars", card_id, actor)
        db.set_inbox_status(draft["inbox_id"], db.ST_APPROVED_OWNER, actor)
    except Exception:
        pass

    context.user_data.pop("ai_draft", None)
    card = db.get_card("cars", card_id)
    await q.message.edit_reply_markup(reply_markup=None)
    await q.message.reply_text(
        note,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Открыть карточку", callback_data="car_open:%d" % card_id)],
            [InlineKeyboardButton("Дозаполнить", callback_data="car_edit:%d" % card_id)]]))
    raise ApplicationHandlerStop

def voice_change_plan(card, data, allowed, override=False):
    """Return bounded field updates; filled values change only by explicit request."""
    changes = []
    skipped = []
    permitted = set(allowed or ())
    for field, value in (data or {}).items():
        if field not in permitted or value in (None, "", []):
            continue
        old = card.get(field)
        if old not in (None, "", 0, []) and not override:
            skipped.append(field)
            continue
        if str(old or "") != str(value):
            changes.append((field, old, value))
    return changes, skipped

def _v165_key(card_id, target, file_id):
    import hashlib as _v165_hashlib
    raw = "%s\0%s\0%s" % (int(card_id), str(target), str(file_id))
    return _v165_hashlib.sha256(raw.encode("utf-8")).hexdigest()

def _v165_limit(target):
    return {"photos": S.PHOTO_LIMIT,
            "condition_photos": S.CONDITION_PHOTO_LIMIT}.get(target, 100)

def _v165_read_rows():
    import fcntl as _v165_fcntl
    import json as _v165_json
    import os as _v165_os
    _v165_os.makedirs(_v165_os.path.dirname(_V165_SPOOL), exist_ok=True)
    with open(_V165_SPOOL_LOCK, "a+", encoding="utf-8") as _v165_guard:
        _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_EX)
        try:
            try:
                with open(_V165_SPOOL, "r", encoding="utf-8") as _v165_file:
                    _v165_lines = _v165_file.readlines()
            except FileNotFoundError:
                _v165_lines = []
        finally:
            _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_UN)
    _v165_rows = []
    for _v165_line in _v165_lines:
        try:
            _v165_row = _v165_json.loads(_v165_line)
            if isinstance(_v165_row, dict) and _v165_row.get("key"):
                _v165_rows.append(_v165_row)
        except Exception:
            continue
    return _v165_rows

def _v165_spool_enqueue(card_id, target, file_id, actor_id, tag=""):
    """Durably accept first; never wait for SQLite or Telegram getFile."""
    import fcntl as _v165_fcntl
    import json as _v165_json
    import os as _v165_os
    import time as _v165_time
    _v165_os.makedirs(_v165_os.path.dirname(_V165_SPOOL), exist_ok=True)
    _v165_event = {
        "key": _v165_key(card_id, target, file_id),
        "card_id": int(card_id),
        "target": str(target),
        "file_id": str(file_id),
        "actor_id": int(actor_id),
        "tag": str(tag or ""),
        "accepted_at": int(_v165_time.time()),
    }
    with open(_V165_SPOOL_LOCK, "a+", encoding="utf-8") as _v165_guard:
        _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_EX)
        try:
            try:
                with open(_V165_SPOOL, "r", encoding="utf-8") as _v165_file:
                    _v165_lines = _v165_file.readlines()
            except FileNotFoundError:
                _v165_lines = []
            _v165_keys = set()
            _v165_same = 0
            for _v165_line in _v165_lines:
                try:
                    _v165_row = _v165_json.loads(_v165_line)
                except Exception:
                    continue
                _v165_keys.add(_v165_row.get("key"))
                if (_v165_row.get("card_id") == int(card_id)
                        and _v165_row.get("target") == str(target)):
                    _v165_same += 1
            if _v165_event["key"] in _v165_keys:
                return {"state": "duplicate", "queued": _v165_same}
            if _v165_same >= _v165_limit(target):
                return {"state": "limit", "queued": _v165_same}
            _v165_payload = (_v165_json.dumps(
                _v165_event, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
            _v165_fd = _v165_os.open(
                _V165_SPOOL,
                _v165_os.O_WRONLY | _v165_os.O_CREAT | _v165_os.O_APPEND,
                0o600,
            )
            try:
                _v165_os.write(_v165_fd, _v165_payload)
                _v165_os.fsync(_v165_fd)
            finally:
                _v165_os.close(_v165_fd)
            return {"state": "accepted", "queued": _v165_same + 1}
        finally:
            _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_UN)

def _v165_spool_remove(keys):
    import fcntl as _v165_fcntl
    import json as _v165_json
    import os as _v165_os
    import tempfile as _v165_tempfile
    _v165_keys = set(keys)
    if not _v165_keys:
        return
    with open(_V165_SPOOL_LOCK, "a+", encoding="utf-8") as _v165_guard:
        _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_EX)
        try:
            try:
                with open(_V165_SPOOL, "r", encoding="utf-8") as _v165_file:
                    _v165_lines = _v165_file.readlines()
            except FileNotFoundError:
                return
            _v165_keep = []
            for _v165_line in _v165_lines:
                try:
                    if _v165_json.loads(_v165_line).get("key") in _v165_keys:
                        continue
                except Exception:
                    pass
                _v165_keep.append(_v165_line)
            _v165_dir = _v165_os.path.dirname(_V165_SPOOL)
            _v165_fd, _v165_tmp = _v165_tempfile.mkstemp(prefix=".media-spool-", dir=_v165_dir)
            try:
                with _v165_os.fdopen(_v165_fd, "w", encoding="utf-8") as _v165_file:
                    _v165_file.writelines(_v165_keep)
                    _v165_file.flush()
                    _v165_os.fsync(_v165_file.fileno())
                _v165_os.replace(_v165_tmp, _V165_SPOOL)
            finally:
                try:
                    _v165_os.unlink(_v165_tmp)
                except FileNotFoundError:
                    pass
        finally:
            _v165_fcntl.flock(_v165_guard.fileno(), _v165_fcntl.LOCK_UN)

def _v166_drain_owned(max_items=100):
    """Drain while the one global drain lock is owned."""
    _v165_rows = _v165_read_rows()[:max(1, int(max_items))]
    _v165_done = []
    _v165_error = ""
    for _v165_row in _v165_rows:
        try:
            _v165_card = card_of(_v165_row["card_id"])
            if not _v165_card:
                _v165_error = "card unavailable"
                continue
            _v165_answer = save_media(
                _v165_card,
                _v165_row["target"],
                _v165_row["file_id"],
                _v165_row["actor_id"],
                _v165_row.get("tag", ""),
            )
            if _v165_answer and any(_v165_word in str(_v165_answer).casefold()
                                    for _v165_word in ("не принят", "не проверен")):
                _v165_error = str(_v165_answer)[:160]
                continue
            _v165_done.append(_v165_row["key"])
        except Exception as _v165_exc:
            _v165_error = "%s: %s" % (type(_v165_exc).__name__, _v165_exc)
            if "locked" in str(_v165_exc).casefold() or "busy" in str(_v165_exc).casefold():
                break
    _v165_spool_remove(_v165_done)
    return {"processed": len(_v165_done),
            "remaining": len(_v165_read_rows()),
            "error": _v165_error, "busy": False}

def _v165_spool_drain(max_items=100):
    """Exactly one worker may mutate card media at a time."""
    import fcntl as _v166_fcntl
    with open(_V165_DRAIN_LOCK, "a+", encoding="utf-8") as _v166_guard:
        try:
            _v166_fcntl.flock(
                _v166_guard.fileno(), _v166_fcntl.LOCK_EX | _v166_fcntl.LOCK_NB)
        except BlockingIOError:
            return {"processed": 0, "remaining": len(_v165_read_rows()),
                    "error": "", "busy": True}
        try:
            return _v166_drain_owned(max_items)
        finally:
            _v166_fcntl.flock(_v166_guard.fileno(), _v166_fcntl.LOCK_UN)

def _v165_media_ids(card, target):
    if not card:
        return []
    try:
        _v165_items = jload(card.get(target))
    except Exception:
        _v165_items = []
    _v165_result = []
    for _v165_item in _v165_items:
        _v165_value = (_v165_item.get("file_id") if isinstance(_v165_item, dict)
                       else _v165_item)
        if _v165_value and _v165_value not in _v165_result:
            _v165_result.append(_v165_value)
    return _v165_result

def _v165_status(card_id, target, session_ids=None):
    _v165_rows = [row for row in _v165_read_rows()
                  if row.get("card_id") == int(card_id)
