class Soedinenie(sqlite3.Connection):
    """Own the process queue only while a write transaction is active."""

    def _pered_zapisyu(self, sql):
        if not _ua_sql_pishet(sql) or getattr(self, "_ua_zapis_v_ocheredi", False):
            return False
        vzyata = ZAMOK.acquire(timeout=ZAMOK_OZHIDANIE)
        if not vzyata:
            raise sqlite3.OperationalError("CRM thread queue timeout")
        self._ochered_vzyata = True
        try:
            _ua_fayl_zahvatit(ZAMOK_OZHIDANIE)
            self._fayl_zaregistrirovan = True
            self._ua_zapis_v_ocheredi = True
            return True
        except Exception:
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass
            raise

    def _otpustit(self):
        self._ua_zapis_v_ocheredi = False
        if getattr(self, "_fayl_zaregistrirovan", False):
            self._fayl_zaregistrirovan = False
            try:
                _ua_fayl_otpustit()
            except Exception:
                pass
        if getattr(self, "_ochered_vzyata", False):
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass

    def cursor(self, factory=None):
        return sqlite3.Connection.cursor(self, factory or _UaKursor)

    def execute(self, sql, parameters=()):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.execute(self, sql, parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executemany(self, sql, seq_of_parameters):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.executemany(self, sql, seq_of_parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executescript(self, sql_script):
        novaya = self._pered_zapisyu(sql_script)
        try:
            return sqlite3.Connection.executescript(self, sql_script)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def _commit_s_povtorom(self):
        import time as _ua_time

        for attempt in range(5):
            try:
                sqlite3.Connection.commit(self)
                return
            except sqlite3.OperationalError as exc:
                text = str(exc).casefold()
                if "locked" not in text and "busy" not in text:
                    raise
                if attempt == 4:
                    raise
                _ua_time.sleep(0.15 * (2 ** attempt))

    def commit(self):
        try:
            self._commit_s_povtorom()
        except Exception:
            try:
                sqlite3.Connection.rollback(self)
            finally:
                self._otpustit()
            raise
        self._otpustit()

    def rollback(self):
        try:
            return sqlite3.Connection.rollback(self)
        finally:
            self._otpustit()

    def close(self):
        try:
            if self.in_transaction:
                sqlite3.Connection.rollback(self)
            sqlite3.Connection.close(self)
        finally:
            self._otpustit()

    def __exit__(self, tip, znachenie, sled):
        try:
            if tip is None:
                self.commit()
            else:
                self.rollback()
        finally:
            try:
                self.close()
            except Exception:
                self._otpustit()
        return False

    def __del__(self):
        self._otpustit()

def connect():
    conn = sqlite3.connect(DB_FILE, timeout=ZAMOK_OZHIDANIE, factory=Soedinenie)
    conn.row_factory = sqlite3.Row
    # Setup pragmas must not hold the transaction queue for a long-lived reader.
    try:
        sqlite3.Connection.execute(conn, "PRAGMA journal_mode=DELETE")
    except Exception:
        pass
    sqlite3.Connection.execute(
        conn, "PRAGMA busy_timeout=%d" % (ZAMOK_OZHIDANIE * 1000)
    )
    sqlite3.Connection.execute(conn, "PRAGMA foreign_keys=ON")
    return conn

def _prepare(image, scale: int):
    from PIL import ImageEnhance, ImageFilter, ImageOps

    if scale > 1:
        image = image.resize(
            (image.width * scale, image.height * scale),
            resample=getattr(__import__("PIL.Image", fromlist=["Resampling"]), "Resampling").LANCZOS,
        )
    image = ImageOps.autocontrast(ImageOps.grayscale(image), cutoff=1)
    image = ImageEnhance.Contrast(image).enhance(1.25)
    return image.filter(ImageFilter.SHARPEN)

def image_text(image_bytes: bytes, hard_seconds: float = DEFAULT_PHOTO_SECONDS) -> str:
    """Run local OCR within the caller's deadline; never use a network model."""
    binary = shutil.which("tesseract")
    if not binary or not image_bytes:
        return ""
    try:
        from PIL import Image
    except Exception:
        return ""

    deadline = time.monotonic() + max(0.5, float(hard_seconds))
    try:
        original = Image.open(io.BytesIO(image_bytes)).convert("RGB")
    except Exception:
        return ""
    width, height = original.size
    if width < 32 or height < 32:
        return ""

    languages = _languages(binary)
    chunks = []

    # A sparse full-page pass finds large labels before the detailed crop passes.
    full_scale = 2 if max(width, height) < 2200 else 1
    full = _prepare(original.copy(), full_scale)
    first = _ocr_one(full, binary, languages, deadline, 11)
    if first:
        chunks.append(first)

    # Right-first overlapping tiles prioritize nested marketplace screenshots
    # commonly forwarded inside Telegram while still covering the whole image.
    tile_w = max(32, int(width * 0.56))
    tile_h = max(32, int(height * 0.34))
    x_positions = [max(0, width - tile_w), 0]
    y_positions = [
        0,
        max(0, int((height - tile_h) * 0.34)),
        max(0, int((height - tile_h) * 0.67)),
        max(0, height - tile_h),
    ]
    for y in y_positions:
        for x in x_positions:
            if time.monotonic() >= deadline:
                break
            tile = original.crop((x, y, min(width, x + tile_w), min(height, y + tile_h)))
            scale = 3 if max(tile.size) < 1800 else 2
            text = _ocr_one(_prepare(tile, scale), binary, languages, deadline, 3)
            if text and text not in chunks:
                chunks.append(text)
    return "\n".join(chunks)

def fields_from_text(text: str, allowed_keys) -> dict:
    """Extract only keys that exist in the live CRM schema."""
    allowed = set(allowed_keys or ())
    data = {}
    raw = str(text or "")
    folded = raw.casefold()

    match = CAR_LINE_RE.search(raw)
    if match:
        _put(data, allowed, "brand", BRANDS[match.group(1).casefold()])
        _put(data, allowed, "model", match.group(2).upper())
        _put(data, allowed, "year", match.group(3))

    vins = VIN_RE.findall(raw.upper())
    vins = [v for v in vins if any(c.isalpha() for c in v) and any(c.isdigit() for c in v)]
    if vins:
        _put(data, allowed, "vin", vins[0].upper())

    if "year" not in data:
        years = re.findall(r"(?<!\d)((?:19|20)\d{2})(?!\d)", raw)
        if years:
            _put(data, allowed, "year", years[0])

    mileage = re.search(
        r"(?<!\d)(\d{1,3}(?:[ .]\d{3})?|\d{1,7})\s*"
        r"(tuc|тыс|тис|тысяч|тисяч)?\.?\s*(km|км)\b",
        folded,
    )
    if mileage:
        value = int(re.sub(r"\D", "", mileage.group(1)))
        if mileage.group(2) and value < 10000:
            value *= 1000
        if 0 < value <= 2_000_000:
            _put(data, allowed, "mileage_km", value)

    if re.search(r"\b(lpg|газ|gaz|gas|fas)\b", folded):
        _put(data, allowed, "fuel", "LPG")
    elif re.search(r"\b(diesel|дизел)\w*\b", folded):
        _put(data, allowed, "fuel", "diesel")
    elif re.search(r"\b(hybrid|гибрид)\w*\b", folded):
        _put(data, allowed, "fuel", "hybrid")
    elif re.search(r"\b(electric|электро|ev)\w*\b", folded):
        _put(data, allowed, "fuel", "electric")
    elif re.search(r"\b(gasoline|petrol|бензин)\w*\b", folded):
        _put(data, allowed, "fuel", "gasoline")

    if re.search(r"\b(automatic|automat|astomat|asromat|автомат)\w*\b", folded):
        _put(data, allowed, "gearbox", "automatic")
    elif re.search(r"\b(manual|механик)\w*\b", folded):
        _put(data, allowed, "gearbox", "manual")

    if re.search(r"\b(awd|4wd|полный|повний)\b", folded):
        _put(data, allowed, "drive", "4wd")
    elif re.search(r"\b(fwd|передний|передній)\b", folded):
        _put(data, allowed, "drive", "fwd")
    elif re.search(r"\b(rwd|задний|задній)\b", folded):
        _put(data, allowed, "drive", "rwd")

    fuel_engine = re.search(
        r"(?:lpg|gas|gaz|fas|газ)[^\n]{0,10}?[,;:\s]\s*"
        r"([1-8])(?:\s*[.,]\s*([0-9]))?\s*(?:l|л|n)\b",
        folded,
    )
    engine = fuel_engine or re.search(
        r"(?<!\d)([1-8])\s*[.,]\s*([0-9])\s*(?:l|л|n)?\b", folded
    )
    if engine:
        fraction = int(engine.group(2) or 0)
        _put(data, allowed, "engine_cc", int(engine.group(1)) * 1000 + fraction * 100)
    else:
        engine = re.search(r"(?<!\d)([1-8])\s*(?:l|л|n)\b", folded)
        if engine:
            _put(data, allowed, "engine_cc", int(engine.group(1)) * 1000)
    return data

def fields_from_image(
    image_bytes: bytes,
    allowed_keys,
    hard_seconds: float = DEFAULT_PHOTO_SECONDS,
) -> dict:
    return fields_from_text(image_text(image_bytes, hard_seconds=hard_seconds), allowed_keys)

def _bump(value, floor):
    """None значит «без ограничения» — не трогаем. Маленькое значение поднимаем."""
    if value is None:
        return None
    try:
        return max(float(value), float(floor))
    except (TypeError, ValueError):
        return floor

def patch_request_timeouts():
    """Заводские 5 секунд в HTTPXRequest заменяем на человеческие."""
    from telegram.request import HTTPXRequest

    orig = HTTPXRequest.__init__
    if getattr(orig, "_ns_wrapped", False):
        return

    @functools.wraps(orig)
    def inner(self, *args, **kwargs):
        # ГЛАВНОЕ: по умолчанию соединение с Telegram всего одно.
        # Пока уходит альбом фото, все остальные запросы стоят в очереди
        # и умирают по таймауту. Даём 16 параллельных соединений.
        try:
            size = int(kwargs.get("connection_pool_size") or 1)
        except (TypeError, ValueError):
            size = 1
        kwargs["connection_pool_size"] = max(size, 16)

        kwargs["read_timeout"] = _bump(kwargs.get("read_timeout", 5), READ_TIMEOUT)
        kwargs["write_timeout"] = _bump(kwargs.get("write_timeout", 5), WRITE_TIMEOUT_TEXT)
        kwargs["connect_timeout"] = _bump(kwargs.get("connect_timeout", 5), CONNECT_TIMEOUT)
        kwargs["pool_timeout"] = _bump(kwargs.get("pool_timeout", 1), POOL_TIMEOUT)
        try:
            return orig(self, *args, **kwargs)
        except TypeError:
            # версия библиотеки не знает таких аргументов — идём как есть
            for k in (
                "read_timeout", "write_timeout", "connect_timeout",
                "pool_timeout", "connection_pool_size",
            ):
                kwargs.pop(k, None)
            return orig(self, *args, **kwargs)

    inner._ns_wrapped = True
    HTTPXRequest.__init__ = inner
    log.info("таймауты соединения подняты")

def _wrap_send(orig, is_media, errors):
    TimedOut, NetworkError, RetryAfter = errors

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        args, kwargs = fix_split_text(orig.__name__, args, kwargs)
        if orig.__name__ == "send_media_group":
            args, kwargs = _dopisat_video(args, kwargs)
        kwargs.setdefault("read_timeout", READ_TIMEOUT)
        kwargs.setdefault("connect_timeout", CONNECT_TIMEOUT)
        kwargs.setdefault(
            "write_timeout", WRITE_TIMEOUT_MEDIA if is_media else WRITE_TIMEOUT_TEXT
        )

        last = None
        for attempt in range(1, RETRIES + 1):
            try:
                # тот же самый файл уже уходил — отправляем по id, без заливки
                sent_id = None
                if orig.__name__ == "send_document":
                    raw = _doc_bytes(kwargs.get("document") or (args[1] if len(args) > 1 else None))
                    if raw:
                        sig = "doc:" + hashlib.md5(raw).hexdigest()
                        cached = _cache_get(sig)
                        if cached:
                            kwargs.pop("document", None)
                            if len(args) > 1:
                                args = (args[0],) + (cached.decode("utf-8"),) + tuple(args[2:])
                            else:
                                kwargs["document"] = cached.decode("utf-8")
                            log.info("файл взят из кэша, без перезаливки")
                        else:
                            sent_id = sig

                result = await orig(self, *args, **kwargs)

                if orig.__name__ == "send_document":
                    try:
                        if sent_id and getattr(result, "document", None):
                            _cache_put(sent_id, result.document.file_id.encode("utf-8"))
                    except Exception:
                        pass
                    asyncio.create_task(_videos_after_html(self, result))
                return result
            except RetryAfter as e:
                last = e
                wait = float(getattr(e, "retry_after", 3)) + 1
                log.warning("флуд-контроль на %s, ждём %.0f c", orig.__name__, wait)
                await asyncio.sleep(wait)
            except (TimedOut, NetworkError) as e:
                last = e
                if attempt == RETRIES:
                    break
                wait = PAUSE * attempt
                log.warning(
                    "сеть подвела на %s, попытка %d из %d, пауза %.0f c",
                    orig.__name__, attempt, RETRIES, wait,
                )
                await asyncio.sleep(wait)
            except TypeError:
                for k in ("read_timeout", "write_timeout", "connect_timeout"):
                    kwargs.pop(k, None)
                return await orig(self, *args, **kwargs)
        raise last

    inner._ns_wrapped = True
    return inner

def _wrap_silent(orig):
    """answer_callback_query живёт секунды: не повторяем и не роняем обработчик."""

    @functools.wraps(orig)
    async def inner(self, *args, **kwargs):
        kwargs.setdefault("read_timeout", 10)
        kwargs.setdefault("write_timeout", 10)
        kwargs.setdefault("connect_timeout", 10)
        kwargs.setdefault("pool_timeout", 10)
        try:
            return await orig(self, *args, **kwargs)
        except TypeError:
            for k in ("read_timeout", "write_timeout", "connect_timeout", "pool_timeout"):
                kwargs.pop(k, None)
            try:
                return await orig(self, *args, **kwargs)
            except Exception:
                return True
        except Exception as e:
            log.warning("не подтвердили нажатие кнопки, идём дальше: %r", e)
            return True

    inner._ns_wrapped = True
    return inner

def patch_card_html_budget():
    """Делаем HTML-файл лёгким: он собирается долго только из-за веса."""
    try:
        sys.path.insert(0, BASE)
        import card_html
    except Exception:
        return
    changed = []
    for name in dir(card_html):
        if name.startswith("_") or not name.isupper():
            continue
        try:
            value = getattr(card_html, name)
        except Exception:
            continue
        if not isinstance(value, int) or isinstance(value, bool):
